package payment

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"time"
)

// egressGuard 平台统一出口守卫：拨号层校验解析后IP，拒绝私网/回环/链路本地/组播/未指定地址
func egressGuard(ctx context.Context, network, addr string) (net.Conn, error) {
	host, port, _ := net.SplitHostPort(addr)
	ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
	if err != nil || len(ips) == 0 {
		return nil, fmt.Errorf("resolve %s failed", host)
	}
	for _, item := range ips {
		if ip := item.IP; ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsUnspecified() || ip.IsMulticast() {
			return nil, fmt.Errorf("blocked non-public ip %s", ip)
		}
	}
	var d net.Dialer
	return d.DialContext(ctx, network, net.JoinHostPort(ips[0].IP.String(), port))
}

var verifyClient = &http.Client{ // 回查专用客户端：强制走 egressGuard，禁用重定向
	Transport:     &http.Transport{DialContext: egressGuard},
	Timeout:       5 * time.Second,
	CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
}

// HandleCallback 支付回调处理器：用回调参数 gateway_url 向渠道网关回查订单状态
func HandleCallback(w http.ResponseWriter, r *http.Request) {
	gatewayURL := r.URL.Query().Get("gateway_url") // 攻击者可控来源
	req, err := http.NewRequestWithContext(r.Context(), http.MethodGet, gatewayURL, nil)
	if err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	resp, err := verifyClient.Do(req) // 唯一出口，经 egressGuard 校验
	if err != nil {
		http.Error(w, "verify failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
}
