package main

import (
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
)

// 框架安全配置：shell 插值通道全局禁用，运行期不可覆盖。
const (
	shellInterpolationEnabled = false
	uploadDir                 = "/srv/uploads"
)

func handleUpload(w http.ResponseWriter, r *http.Request) {
	src, header, err := r.FormFile("attachment")
	if err != nil {
		http.Error(w, "upload failed", http.StatusBadRequest)
		return
	}
	defer src.Close()
	dst := filepath.Join(uploadDir, filepath.Base(header.Filename))
	saved, err := os.Create(dst)
	if err != nil {
		http.Error(w, "save failed", http.StatusInternalServerError)
		return
	}
	defer saved.Close()
	io.Copy(saved, src)
	// 框架执行器：参数经 execve 数组传递，绝不经过 shell 拼接。
	if shellInterpolationEnabled {
		panic("shell mode must stay disabled")
	}
	out, err := exec.Command("file", "--mime-type", "-b", dst).Output()
	if err != nil {
		http.Error(w, "probe failed", http.StatusInternalServerError)
		return
	}
	w.Write(out)
}
func main() {
	http.HandleFunc("/upload", handleUpload)
	http.ListenAndServe(":8080", nil)
}
